GLOSSARY = [
    ("Nanoparticle", "Particle with at least one dimension between 1 and 100 nm.", "Basics"),
    ("Quantum dot", "Semiconductor nanocrystal with size-tuned optical emission.", "Basics"),
    ("Band gap", "Energy range with no electron states; sets optical and electronic behaviour.", "Physics"),
    ("Scherrer equation", "D = K·λ/(β·cosθ): crystallite size from XRD peak broadening.", "Characterization"),
    ("Bragg's law", "nλ = 2d·sinθ: diffraction condition for crystal planes.", "Characterization"),
    ("FWHM", "Full width at half maximum of a diffraction or spectral peak.", "Characterization"),
    ("XRD", "X-ray diffraction: probes crystal structure and crystallite size.", "Characterization"),
    ("SEM", "Scanning electron microscopy: surface imaging with electrons.", "Characterization"),
    ("TEM", "Transmission electron microscopy: atomic-scale internal imaging.", "Characterization"),
    ("DLS", "Dynamic light scattering: hydrodynamic size in suspension.", "Characterization"),
    ("UV-Vis", "Ultraviolet-visible spectroscopy: plasmon peaks and band gaps.", "Characterization"),
    ("Plasmon resonance", "Collective electron oscillation giving metal nanoparticles colour.", "Physics"),
    ("CVD", "Chemical vapour deposition: gas-phase thin-film and nanotube growth.", "Synthesis"),
    ("Green synthesis", "Nanoparticle synthesis using plant extracts instead of harsh reductants.", "Synthesis"),
    ("Sintering", "Fusing particles with heat to form conductive traces or dense parts.", "Processing"),
    ("Biocompatible", "Safe for contact with living tissue at the intended dose.", "Safety"),
    ("Zeta potential", "Surface charge measure predicting suspension stability.", "Characterization"),
    ("Photoluminescence", "Light emission after photon absorption (quantum dots, C-dots).", "Physics"),
]


def seed_all(db) -> None:
    from .models import Article, Batch, GlossaryTerm, LessonRow, Material, Reply, Thread
    if db.query(Material).count() == 0:
        for m in MATERIALS:
            d = dict(m)
            db.add(Material(id=d.pop("id"), name=d.pop("name"), formula=d.pop("formula"),
                            category=d.pop("category"), data=d))
    if db.query(Article).count() == 0:
        for a in ARTICLES:
            db.add(Article(id=a["id"], title=a["title"], source=a["source"], date=a["date"],
                           read_minutes=a["read_minutes"], art=a["art"], accent=a["accent"],
                           excerpt=a["excerpt"], tags=a["tags"], body=a["body"]))
    if db.query(LessonRow).count() == 0:
        for le in LESSONS:
            db.add(LessonRow(course_id=le["course_id"], lesson_id=le["lesson_id"],
                             title=le["title"], minutes=le["minutes"], body=le["body"], quiz=le["quiz"]))
    if db.query(GlossaryTerm).count() == 0:
        for term, definition, tag in GLOSSARY:
            db.add(GlossaryTerm(term=term, definition=definition, tag=tag))
    if db.query(Thread).count() == 0:
        t1 = Thread(id="th_seed1", title="Best dispersant for Ag nanoparticle ink?", tag="Formulation",
                    author="Maya R.",
                    body="My silver traces crack after sintering at 150C. Which dispersant keeps 40nm Ag stable in ethanol without killing conductivity?")
        t2 = Thread(id="th_seed2", title="Scherrer vs TEM sizes disagree - normal?", tag="Characterization",
                    author="Prof. S.",
                    body="XRD gives 18 nm, TEM shows 35 nm particles. Is my FWHM wrong or is this expected?")
        t3 = Thread(id="th_seed3", title="Showcase: ZnO nanorod gas sensor array", tag="Showcase", author="Aarav",
                    body="Room-temperature response to 50 ppm ethanol using the Nano Sensor project template.")
        t1.likes_count, t2.likes_count, t3.likes_count = 12, 8, 21
        db.add_all([t1, t2, t3])
        db.flush()
        db.add(Reply(thread_id="th_seed1", author="Dev K.",
                     text="Try 1 wt% PVP (10k) + slow ramp 2C/min. Fixed the same cracking for me."))
        db.add(Reply(thread_id="th_seed2", author="Nano Team",
                     text="Expected - Scherrer measures coherent crystallites, TEM sees whole particles. Compare both in Lab Tools."))
    db.commit()
